inline const WeaponSpec *weaponSpec(int item) {
    int lo=0,hi=int(sizeof(weaponSpecs)/sizeof(weaponSpecs[0]));
    while(lo<hi){int mid=(lo+hi)/2;if(weaponSpecs[mid].item<item)lo=mid+1;else hi=mid;}
    return lo<int(sizeof(weaponSpecs)/sizeof(weaponSpecs[0]))&&weaponSpecs[lo].item==item?&weaponSpecs[lo]:nullptr;
}
